"""Metodología en tarjetas: objetivo, reglas y límites en lenguaje claro."""
import html
from analytics import audit
from ui_design import icon
def cards(d,payload):
    a=audit(d,payload)
    return [
      {'title':'1. Qué queremos conocer','icon':'chart','color':'#2ee6a6','tag':'Objetivo','text':'Localizar diferencias de puntualidad y dimensionar demoras, cancelaciones y desvíos para priorizar un diagnóstico operativo. El dashboard describe los datos; no predice vuelos ni demuestra causas.'},
      {'title':'2. Qué datos estamos usando','icon':'document','color':'#5b8def','tag':'Cobertura real','text':f'{a["rows"]:,} agregados representan {a["metrics"]["ops"]:,} operaciones entre {a["date_min"]} y {a["date_max"]}. Una fila combina año, mes, aerolínea, origen y radio: no equivale a un vuelo individual.'},
      {'title':'3. Cómo leer los nombres','icon':'plane','color':'#2ec4b6','tag':'Código — nombre completo','text':'Los códigos se conservan como identificadores; los nombres completos facilitan la lectura. Ejemplos: AA — American Airlines y ATL — Hartsfield Jackson Atlanta International Airport. Los nombres son referencias descriptivas, no cambios en las cifras históricas.'},
      {'title':'4. Cómo se calculan los KPI','icon':'pie','color':'#2ee6a6','tag':'Cocientes de sumas','text':'OTP = puntuales / operaciones; demora ≥15, demora ≥60, cancelación y desvíos usan el mismo denominador. Se multiplican por 100 para mostrarlos en %. Demora media = minutos totales / llegadas con demora ≥15. Si no hay denominador, se muestra “Sin datos”. Nunca se promedian porcentajes sin ponderar.'},
      {'title':'5. Qué cambia al filtrar','icon':'calendar','color':'#5b8def','tag':'Dos alcances diferentes','text':'Año, mes, aerolínea y radio filtran el cubo y sus KPI. El selector de aeropuerto solo modifica el resumen de hubs y los mapas. Los horarios y hubs no tienen claves para cruzarlos con el cubo. Marco del proyecto resume la base completa.'},
      {'title':'6. Cómo cuidamos la calidad','icon':'shield','color':'#f5b942','tag':'Datos auditados','text':f'Hay {a["metrics"]["unclassified"]:,} operaciones sin categoría: se conservan como “Sin clasificar”. Se excluyen {a["invalid_cause_rows"]:,} filas solo del análisis de causas porque sus minutos no concilian (tolerancia: 1 minuto). La cobertura de causas válidas es {a["metrics"]["causeCoverage"]:.2f}% de las operaciones.'},
      {'title':'7. Cómo comparar los años','icon':'calendar','color':'#f5b942','tag':'2026 es parcial','text':'2021–2025 incluyen 12 meses; 2026 llega hasta mayo. Para comparar 2025 y 2026, usar enero–mayo en ambos. Incluso con los mismos meses, la composición de aerolíneas y radios puede cambiar.'},
      {'title':'8. Qué significa la incertidumbre','icon':'shield','color':'#b07cff','tag':'Wilson 95%','text':'El intervalo Wilson describe precisión bajo un modelo binomial con independencia entre operaciones. No mide sesgo, errores del origen, dependencia entre vuelos ni desempeño futuro. El soporte mínimo de 30 es un filtro de volumen, no una garantía de representatividad.'},
      {'title':'9. Cómo leer el mapa','icon':'pin','color':'#2ec4b6','tag':'Ubicación y rendimiento','text':'Mapa real usa calles, ciudades e imágenes satelitales de Esri, con zoom y fichas de aeropuertos; requiere Internet. El mapa sin conexión conserva los puntos sobre límites geográficos. Los puntos muestran el resumen de hubs, sin fecha ni aerolínea. Color: OTP; tamaño: volumen. Un mapa de aeropuertos no equivale a un análisis estatal.'},
      {'title':'10. Qué no se puede concluir','icon':'alert','color':'#f07178','tag':'Límites del dataset','text':'OriginState solo contiene US. No hay detalle suficiente para un ciclo semanal ni para cruzar día, hora y radio. No se fabrican patrones ni se fijan reglas de conexiones de 45 minutos. Los límites de distancia de corto, medio y largo no están documentados.'},
      {'title':'11. Cómo entender colores y metas','icon':'pie','color':'#2ee6a6','tag':'Diseño y accesibilidad','text':'Verde y turquesa identifican desempeño y series; dorado señala referencias; rojo destaca atención y límites. Valores, títulos y etiquetas acompañan el color. El 80% de OTP es una referencia interna ajustable: no se presenta como una norma oficial del DOT.'},
      {'title':'12. Cómo se reproduce el análisis','icon':'document','color':'#5b8def','tag':'Trazabilidad e IA','text':'El JSON original, catálogos, exclusiones, notebook, Python y DAX permiten revisar los cálculos. JavaScript y Python se contrastan con los mismos filtros. La IA ayudó a preparar código y textos; las cifras se recalculan. Power BI requiere verificación final de apertura, medidas y visuales en Desktop.'}
    ]
def render_cards(d,payload):
    out='<div class="method-intro"><h2>Metodología paso a paso</h2><p>Qué analizamos, cómo calculamos y hasta dónde permiten concluir los datos.</p></div><div class="method-grid">'
    for c in cards(d,payload):
        out+=f'<article class="method-card" style="--method-color:{c["color"]}"><div class="method-heading">{icon(c["icon"],"chart-icon")}<span>{html.escape(c["tag"])}</span></div><h3>{html.escape(c["title"])}</h3><p>{html.escape(c["text"])}</p></article>'
    return out+'</div>'
